#!/usr/bin/env python3
# Some portions generated by Codex. Independent-fork factorial analysis, no result trimming.
import pathlib,sys,json,statistics,math,re
root=pathlib.Path(sys.argv[1])
def rows(path):
 out=[]
 for line in path.read_text().splitlines():
  if line.startswith('audit '):out.append(dict(x.split('=',1) for x in line.split()[1:]))
 if not out:raise ValueError(f'No results: {path}')
 return out
ref=rows(root/'reference.log')[0]; result={}
for regime in ('regular','interpreted','janino'):
 fs=[]
 for f in sorted(root.glob(regime+'-??-[ABCD].log')):
  rs=rows(f)
  for r in rs:
   if any(r[k]!=ref[k] for k in ('rows','checksum','checksum2')):raise ValueError(f'Wrong results: {f}')
  measured=[r for r in rs if int(r['run'])>=0]
  allocation=[]
  for line in f.read_text().splitlines():
   if line.startswith('run='):
    d=dict(t.split('=',1) for t in line.split() if '=' in t)
    if int(d['run'])>=0:allocation.append(int(d['threadAllocated']))
  if len(allocation)!=10:raise ValueError(f'Missing allocations: {f}')
  if len(measured)!=10 or len(rs)!=30:raise ValueError(f'Wrong iterations: {f}')
  vals=[int(r['totalNs'])/1e6 for r in measured]
  gc=pathlib.Path(str(f)+'.gc.log')
  pauses=[float(x) for x in re.findall(r'Pause[^\n]*? ([0-9.]+)ms$',gc.read_text(),re.M)] if gc.exists() else []
  fs.append({'file':f.name,'arm':f.stem[-1],'meanMs':statistics.mean(vals),'minMs':min(vals),'maxMs':max(vals),
             'firstRowMs':statistics.mean(int(r['firstRowNs'])/1e6 for r in measured),
             'closeMeanMs':statistics.mean(int(r['closeNs'])/1e6 for r in measured),
             'allocationMeanBytes':statistics.mean(allocation),'byIndexMs':vals,
             'wholeJvmGc':{'pauseCount':len(pauses),'totalPauseMs':sum(pauses),'maxPauseMs':max(pauses,default=0),'includesWarmupAndStartup':True}})
 if len(fs)!=16:raise ValueError(f'Incomplete route: {regime}')
 arms={}
 for arm in 'ABCD':
  f=[x for x in fs if x['arm']==arm]; means=[x['meanMs'] for x in f]
  if len(f)!=4:raise ValueError((regime,arm))
  arms[arm]={'meanMs':statistics.mean(means),'forkMinMs':min(means),'forkMaxMs':max(means),
             'firstRowMeanMs':statistics.mean(x['firstRowMs'] for x in f),
             'allocationMeanBytes':statistics.mean(x['allocationMeanBytes'] for x in f),
             'measuredIndexMeanMs':[statistics.mean(x['byIndexMs'][i] for x in f) for i in range(10)]}
 pairs=[('B','A'),('C','A'),('D','A'),('D','B'),('D','C')]; contrasts={}
 for treatment,control in pairs:
  a=arms[control]['meanMs'];b=arms[treatment]['meanMs']
  contrasts[treatment+'/'+control]={'latencyReductionPercent':100*(1-b/a),'throughputIncreasePercent':100*(a/b-1)}
 blocks=[]
 for i in range(0,16,4):
  m={x['arm']:x['meanMs'] for x in fs[i:i+4]}
  if set(m)!=set('ABCD'):raise ValueError(f'Bad block: {regime} {i}')
  blocks.append({'block':i//4+1,'latencyReductionPercent':{t+'/'+c:100*(1-m[t]/m[c]) for t,c in pairs},
                 'logInteraction':math.log(m['D'])-math.log(m['B'])-math.log(m['C'])+math.log(m['A']),
                 'interactionRatio':m['D']*m['A']/(m['B']*m['C'])})
 result[regime]={'arms':arms,'contrasts':contrasts,'blocks':blocks,'forks':fs}
print(json.dumps({'scope':'SOURCE_PULL x writer guard, frozen previous measured baseline, not main',
                  'reference':{k:ref[k] for k in ('rows','checksum','checksum2')},
                  'warning':'Within-JVM measurements are not independent forks. Interaction below1 alone does not establish synergy without consistent effects beyond noise.',
                  'results':result},indent=2))
